<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login | Grupo BCMR</title><link rel="stylesheet" href="app.css"><style>.login-wrap{min-height:100vh;display:grid;place-items:center;padding:20px}.login-card{width:min(440px,100%);background:#fff;border:1px solid var(--border);border-radius:20px;padding:28px}.login-card h1{margin:8px 0 6px}.login-card label{display:grid;gap:6px;margin-top:14px;color:var(--muted);font-size:13px}.login-card input{padding:12px 14px;border:1px solid var(--border);border-radius:10px;font-size:16px}.login-card .btn{width:100%;margin-top:18px}.login-msg{min-height:20px;margin-top:12px;color:var(--dangerText);font-size:13px}</style></head><body><main class="login-wrap"><form id="loginForm" class="login-card"><div class="brand-mark">BCMR</div><span class="eyebrow">3 empresas integradas</span><h1>Grupo BCMR Admin</h1><p style="color:var(--muted);margin-top:0">Acesse o painel administrativo.</p><label>E-mail<input id="email" type="email" autocomplete="username" required></label><label>Senha<input id="senha" type="password" autocomplete="current-password" required></label><button class="btn primary" type="submit">Entrar</button><div id="msg" class="login-msg" aria-live="polite"></div></form></main><script>
const form=document.getElementById('loginForm');form.addEventListener('submit',async e=>{e.preventDefault();const msg=document.getElementById('msg');msg.textContent='Entrando...';try{const r=await fetch('api/auth/login.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:document.getElementById('email').value,senha:document.getElementById('senha').value})});const j=await r.json();if(!j.status)throw new Error(j.mensagem||'Falha no login');location.href='index.php';}catch(err){msg.textContent=err.message;}});
</script></body></html>
